const localUrl = z
  .string()
  .max(2048)
  .refine((value) => {
    if (!value) return true;
    if (/[\s\\]/.test(value)) return false;
    try {
      const u = new URL(value);
      return (
        ["http:", "https:"].includes(u.protocol) &&
        ["127.0.0.1", "localhost", "[::1]"].includes(u.hostname) &&
        !u.username &&
        !u.password &&
        u.port !== "0"
